def build_all_specs() -> dict[str, AgentSpec]:
    """Build AgentSpec objects for all agents. Returns dict keyed by agent_id."""
    _TIER_MAP = {t.value: t for t in AgentTier}
    _DIV_MAP  = {d.value: d for d in AgentDivision}
    specs: dict[str, AgentSpec] = {}
    for (aid, name, div, tier, parent, autonomy, spec, model) in _RAW:
        div_key = div if div in _DIV_MAP else "intelligence"
        tier_key = tier if tier in _TIER_MAP else "junior"
        agent_tier = _TIER_MAP.get(tier_key, AgentTier.JUNIOR)
        agent_div  = _DIV_MAP.get(div_key, AgentDivision.INTELLIGENCE)
        memory_scopes = _DIVISION_MEMORY_SCOPES.get(div, [MemoryScope.TASK_LOCAL])
        specs[aid] = AgentSpec(
            agent_id=aid,
            agent_name=name,
            tier=agent_tier,
            division=agent_div,
            parent_agent_id=parent,
            autonomy_level=_AUTONOMY_MAP.get(autonomy, AutonomyLevel.L3),
            specialization=spec,
            capabilities=spec.split(", "),
            memory_scopes=memory_scopes,
            max_concurrent_tasks=_TIER_MAX_TASKS.get(tier, 5),
            confidence_threshold=_TIER_CONF_THRESHOLD.get(tier, 0.70),
            escalation_agent_id=parent,
            model_preference=model,
        )
    return specs


def get_agents_by_division(division: str) -> list[AgentSpec]:
    all_specs = build_all_specs()
    return [s for s in all_specs.values() if s.division.value == division]


def get_agents_by_tier(tier: str) -> list[AgentSpec]:
    all_specs = build_all_specs()
    return [s for s in all_specs.values() if s.tier.value == tier]


def get_children(parent_id: str) -> list[AgentSpec]:
    all_specs = build_all_specs()
    return [s for s in all_specs.values() if s.parent_agent_id == parent_id]


